class ViewHandler:
    def __init__(self, factories: dict[str, Callable[[Model], View]]):
        self._factories = factories; self._open: dict[str, View] = {}; self._next = 0
    def open(self, kind: str, model: Model) -> str:
        self._next += 1; vid = f"v{self._next}"
        self._open[vid] = self._factories[kind](model)   # create + register
        return vid                                       # handle, not the view
    def close(self, vid: str) -> None:
        self._open.pop(vid).destroy()                    # unregister, then dispose
    def notify(self, model: Model) -> None:
        for view in list(self._open.values()):           # snapshot: views may close
            view.update(model)
